import json
from pathlib import Path
W=Path(__file__).resolve().parent
assets=json.loads((W/'assets.json').read_text('utf8'));spec={};inspection=[]
deferred=json.loads((W/'overlap-mask.json').read_text('utf8'))['selectedPhillipsDeferredConcepts']
descriptions={
'AD-01.webp':('Aggregate-demand graph with solid AD0 and dashed AD1 to its right on numbered price-level and real-GDP axes.','The horizontal axis is real GDP, numbered from 0 to 300; the vertical axis is price level, numbered from 0 to 140. Solid blue AD0 slopes downward from approximately (0,100) to (200,0). Dashed blue AD1 lies above and right of AD0, running from approximately (0,125) to (260,0). At price level 50, AD0 is near GDP 100 and AD1 near GDP 155. These are approximate readings of hand-drawn lines; the diagram has no aggregate-supply curve.'),
'AD-02.webp':('Aggregate-demand graph with solid AD0 and dashed AD1 to its left on numbered price-level and real-GDP axes.','The horizontal axis is real GDP, numbered from 0 to 300; the vertical axis is price level, numbered from 0 to 140. Solid blue AD0 slopes downward from approximately (0,120) to (240,0). Dashed blue AD1 lies below and left of AD0, running from approximately (0,95) to (190,0). At price level 45, AD0 is near GDP 150 and AD1 near GDP 100. These are approximate readings of hand-drawn lines; no aggregate-supply curve is shown.'),
'AS-01.webp':('Short-run aggregate-supply graph with solid AS0 and dashed AS1 above and left of it on numbered axes.','The horizontal axis is real GDP and the vertical axis is price level; both are numbered from 0 to 250. Solid red AS0 slopes upward, near price 70 at GDP 0 and near price 150 at GDP 150. Dashed red AS1 lies above and left of AS0, near price 115 at GDP 0 and near price 190 at GDP 150. Both lines continue upward to the right. These coordinates are approximate readings of hand-drawn curves. No AD or LRAS curve is drawn.'),
'AS-02.webp':('Short-run aggregate-supply graph with solid AS0 and dashed AS1 below and right of it on numbered axes.','The horizontal axis is real GDP and the vertical axis is price level; both are numbered from 0 to 250. Solid red AS0 slopes upward from approximately (0,75) toward (230,190). Dashed red AS1 lies below and right of AS0, running from approximately (0,35) toward (230,150). At GDP 150, the curves are near price levels 150 and 110 respectively. These are approximate readings of hand-drawn curves. No AD or LRAS curve is drawn.'),
'LRAS-01.webp':('AD-AS graph with two demand curves, two short-run supply curves, vertical LRAS0 at GDP 100 and points A through D.','The horizontal axis is real GDP and the vertical axis is price level. Blue AD0 and dashed AD1 slope downward; AD1 lies to the right of AD0. Red SRAS0 and dashed SRAS1 slope upward; SRAS1 lies above and left of SRAS0. LRAS0 is vertical at real GDP 100. Coordinates are (GDP, price level): C is the AD0-SRAS0 intersection at (100,125); D is AD1-SRAS0 at (125,150); B is AD1-SRAS1 at (100,175); A is AD0-SRAS1 at (75,150). C and B lie on LRAS0. Dashed guides connect the labeled points with their axis coordinates.'),
'LRAS-02.webp':('AD-AS graph with AD0, SRAS0, SRAS1, vertical LRAS0 and LRAS1, and intersections A and B.','The horizontal axis is real GDP and the vertical axis is price level. Blue AD0 slopes downward. Red SRAS0 slopes upward; dashed SRAS1 lies below and right of SRAS0. LRAS0 is vertical at GDP 100 and dashed LRAS1 is vertical to its right at GDP 115. A, the AD0-SRAS0-LRAS0 intersection, is at (100,125). B, the AD0-SRAS1-LRAS1 intersection, is at (115,110). Dashed guides connect A and B to the axes.'),
'ADAS-01.webp':('AD-AS graph with AD0, rightward AD1, fixed AS0 and marked intersections A and B.','The horizontal axis is real GDP and the vertical axis is price level. Solid blue AD0 and dashed blue AD1 slope downward, with AD1 above and right of AD0. Solid red AS0 slopes upward. Point A is AD0-AS0 at (150,125); point B is AD1-AS0 at (175,137.5). Dashed guides connect the intersections to the axis values. No LRAS line is drawn.'),
'ADAS-02.webp':('AD-AS graph with two demand curves, two short-run supply curves, and four marked intersections.','The horizontal axis is real GDP and the vertical axis is price level. Solid blue AD0 and dashed blue AD1 slope downward; AD1 lies above and right of AD0. Solid red AS0 and dashed red AS1 slope upward; AS1 lies above and left of AS0. All four lines are straight. Coordinates are (GDP, price level): A is AD0-AS0 at (75,100); B is AD1-AS0 at (100,125); C is AD1-AS1 at (75,150); D is AD0-AS1 at (50,125). A numbered grid gives the coordinates. AS1 continues through (25,100). No LRAS line is drawn.')}
for a in assets:
 name=a['filename'];protected=a['conceptId'] in deferred;desc=descriptions.get(name) if not protected else None
 after={'imageAlt':desc[0],'graphDescription':desc[1]} if desc else {k:a[k] for k in ['imageAlt','graphDescription']}
 if desc and name=='AS-01.webp':after['graphDescription']=after['graphDescription'].replace('near price 150 at GDP 150.', 'near price 150 at GDP 150, and near price 190 at GDP 230.')
 reason=('Correct approximate raster coordinates and remove economic interpretation from shared visual evidence.' if name.startswith(('AD-','AS-')) else 'Retain visible axes, labels and intersections; remove the causal or self-adjustment answer from shared visual evidence.') if desc else ('Visually inspected for AD-AS integration and retained unchanged under the Phillips audit boundary.' if protected else 'Detailed axes, symbolic intersections and curve positions match the inspected image; retain the valid evidence contract.')
 if desc:
  for k in [a['runtimePath'],a['sourceAssetPath']]:spec[k]=after
 inspection.append(dict(runtimePath=a['runtimePath'],concept=a['conceptId'],filename=name,sha256=a['sha256'],visuallyInspected=True,protectedPhillips=protected,contractCorrected=bool(desc),reason=reason,before={k:a[k] for k in ['imageAlt','graphDescription']},after=after,bytesChanged=False))
for n,x in [('accessibility-spec.json',spec),('accessibility-inspection.json',inspection)]:
 (W/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n','utf8')
# Adapt the already validated staging and browser harnesses, preserving the five Phillips definitions byte-for-byte semantically.
p=(W.parent/'.saving-work/stage.mjs').read_text('utf8').replace('.saving-work','.adas-work').replace("assert(total===268", "assert(total===728").replace('graphCount:60','graphCount:161').replace('Saving, Investment, Budgets & Debt audit validation','AD-AS, Fiscal Policy & Stabilization audit validation').replace('macro-saving-investment-budgets-debt-audit','adas-fiscal-stabilization-audit')
p=p.replace("const sources=read('sources.json'),", "const protectedConcepts=read('overlap-mask.json').selectedPhillipsDeferredConcepts;\nconst sources=read('sources.json'),")
p=p.replace('const m=lib.concepts[c];','const m=lib.concepts[c]; if(protectedConcepts.includes(c))continue;')
p=p.replace("reason:s?.reason||'Synchronize inline accessibility metadata with the visually verified approved asset contract.'", "reason:s?.reason||(old.image!==q.image?'Resolve the legacy image reference to its existing registered runtime asset path.':'Synchronize inline accessibility metadata with the visually verified approved asset contract.')")
p=p.replace('for(const c of sources)for(const a of lib.concepts[c].assetMetadata||[]){','for(const c of sources.filter(c=>!protectedConcepts.includes(c)))for(const a of lib.concepts[c].assetMetadata||[]){')
p=p.replace('// Exact preservation of module',"for(const c of protectedConcepts)assert(same(lib.concepts[c],base.concepts[c]),'Protected Phillips changed '+c);\n// Exact preservation of module")
(W/'stage.mjs').write_text(p,'utf8')
p=(W.parent/'.saving-work/browser.cjs').read_text('utf8').replace('.saving-work','.adas-work').replace('43297','PG3-MEQ-L-004')
p=p.replace('return {id,zoomOK,description:', 'return {id,concept:q.primaryConceptId,zoomOK,description:')
p=p.replace("if(graphChecks.some(c=>!c.loaded||!c.embeddedImages||!c.text||!c.zoomOK||!c.description))", "const protectedConcepts=JSON.parse(fs.readFileSync('.adas-work/overlap-mask.json','utf8')).selectedPhillipsDeferredConcepts;\n if(graphChecks.some(c=>!protectedConcepts.includes(c.concept)&&(!c.loaded||!c.embeddedImages||!c.text||!c.zoomOK||!c.description)))")
p=p.replace('all ordinary/checkpoint graph questions decode and their click-to-enlarge image opens','all core AD-AS/fiscal ordinary/checkpoint graph questions decode and their click-to-enlarge image opens; protected Phillips results are individually recorded')
(W/'browser.cjs').write_text(p,'utf8')
print('Inspected 27 asset registrations / 20 distinct image files; corrected eight shared graph contracts across 14 concept metadata entries; generated scoped staging and browser harnesses.')
